from fastapi import APIRouter, Depends, HTTPException

async def verify_document_access(
    document_id: str,
    user: User = Depends(get_current_user),
    doc_repo: DocumentRepository = Depends(get_document_repo)
) -> Document:
    doc = await doc_repo.get_by_id(document_id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")
    if doc.owner_id != user.id and user.id not in doc.permitted_collaborators:
        raise HTTPException(status_code=403, detail="Forbidden: user lacks access to this contract")
    return doc

router = APIRouter(prefix="/legal/contracts")

@router.get("/{document_id}/confidential-clauses")
async def get_contract_clauses(
    doc: Document = Depends(verify_document_access, use_cache=False)
):
    return {"document_id": doc.id, "title": doc.title, "clauses": doc.secret_clauses}
